                for edit in record["inverse"].as_array().unwrap() {
                    let after = edit["after"].as_str().unwrap();
                    if output.matches(after).count() != 1 {
                        return None;
                    }
                    output = output.replacen(after, edit["before"].as_str().unwrap(), 1);
